fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Promote to i32 for safe arithmetic
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    let mut fuel = b;
    // pos = 0 means at x=0 endpoint, pos = 1 means at x=a endpoint
    let mut pos = 0;
    let mut refueled = false;

    for leg in 1..=k {
        // 1) Drive from current endpoint to the station
        let dist_to_station = if pos == 0 { f } else { a - f };
        if fuel < dist_to_station {
            return -1;
        }
        fuel -= dist_to_station;

        // 2) Figure out how far we must go on from the station
        //    before the next chance to refuel:
        //    - If this is the last leg, we only need to reach the endpoint.
        //    - Otherwise, we must be able to go to the endpoint and then
        //      back to the station (so we can refill there for the following leg).
        let dist_to_endpoint = if pos == 0 { a - f } else { f };
        let needed = if leg == k {
            dist_to_endpoint
        } else {
            dist_to_endpoint * 2
        };

        // 3) If our current fuel is insufficient for 'needed', we refuel now.
        //    If even a full tank < needed, it's impossible.
        if fuel < needed {
            if b < needed {
                return -1;
            }
            fuel = b;
            refueled = true;
        }

        // 4) Finally drive from the station to the endpoint
        if fuel < dist_to_endpoint {
            return -1;
        }
        fuel -= dist_to_endpoint;

        // 5) Arrive at the far endpoint and flip direction
        pos ^= 1;
    }

    // If we ever refueled, we return 1; otherwise 0
    if refueled { 1 } else { 0 }
}

